// Node.js's zlib from an npm package (tests/node/zlib.js as a module): prints what it found; the same
// package under Node.js prints the same.
module.exports = function run() {
  let pending = 3;
  let done;
  const finished = new Promise((resolve) => { done = resolve; });
  const settle = () => { if (--pending === 0) done(); };
  // zlib: one-shot and streaming deflate, gzip, raw, unzip, brotli and zstd, dictionaries, errors
  const zlib = require('zlib');
  const input = Buffer.from('hello hello hello hello zlib '.repeat(200) + 'ünïcode');
  const hex = (b) => b.toString('hex');
  for (const [c, d] of [['deflateSync', 'inflateSync'], ['gzipSync', 'gunzipSync'], ['deflateRawSync', 'inflateRawSync'], ['brotliCompressSync', 'brotliDecompressSync'], ['zstdCompressSync', 'zstdDecompressSync']]) {
    const packed = zlib[c](input);
    console.log(c, packed.length < input.length, zlib[d](packed).equals(input));
  }
  console.log('deflate bytes', hex(zlib.deflateSync('abc')), hex(zlib.deflateRawSync('abc', { level: 9 })), hex(zlib.gzipSync('abc')).slice(0, 8));
  console.log('brotli bytes', hex(zlib.brotliCompressSync('abc')), hex(zlib.brotliCompressSync('abc', { params: { [zlib.constants.BROTLI_PARAM_QUALITY]: 4 } })));
  console.log('zstd bytes', hex(zlib.zstdCompressSync('abc')));
  console.log('unzip', zlib.unzipSync(zlib.gzipSync('g')).toString(), zlib.unzipSync(zlib.deflateSync('d')).toString());
  console.log('multi-member', zlib.gunzipSync(Buffer.concat([zlib.gzipSync('one '), zlib.gzipSync('two')])).toString());
  const dict = Buffer.from('hello zlib');
  console.log('dictionary', zlib.inflateSync(zlib.deflateSync(input, { dictionary: dict }), { dictionary: dict }).equals(input));
  for (const [name, fn] of [['bad data', () => zlib.inflateSync(Buffer.from('not zlib data'))], ['truncated', () => zlib.gunzipSync(zlib.gzipSync(input).subarray(0, 30))],
    ['missing dict', () => zlib.inflateSync(zlib.deflateSync('x', { dictionary: dict }))], ['bad brotli', () => zlib.brotliDecompressSync(Buffer.from([1, 2, 3, 4]))],
    ['bad zstd', () => zlib.zstdDecompressSync(Buffer.from('nope nope'))], ['bad level', () => zlib.deflateSync('x', { level: 42 })]]) {
    try {
      fn();
      console.log(name, 'no error');
    } catch (e) {
      console.log(name, e.name, e.code, e.errno, e.message);
    }
  }
  console.log('crc32', zlib.crc32('hello'), zlib.crc32(Buffer.from('hello'), 7));
  zlib.deflate(input, (err, out) => {
    console.log('async deflate', err, zlib.inflateSync(out).equals(input));
    zlib.gunzip(Buffer.from('garbage'), (e) => { console.log('async error', e.code, e.message); settle(); });
  });
  const gz = zlib.createGzip();
  const chunks = [];
  gz.on('data', (c) => chunks.push(c));
  gz.on('end', () => { console.log('stream', zlib.gunzipSync(Buffer.concat(chunks)).toString()); settle(); });
  gz.write('streamed ');
  gz.write(Buffer.from('chunks'));
  gz.end();
  const { promisify } = require('util');
  promisify(zlib.brotliCompress)(input).then((b) => { console.log('promisified', zlib.brotliDecompressSync(b).equals(input)); settle(); });
  console.log('constants', zlib.constants.Z_BEST_COMPRESSION, zlib.constants.BROTLI_OPERATION_FINISH, typeof zlib.constants.ZSTD_e_end, zlib.codes.Z_DATA_ERROR);
  return finished;
};
